-- Query surface beyond the extended corpus, against PostgreSQL over the same
-- rows: time zones, JSON, arrays, recursive CTEs, large IN lists, math,
-- strings, window frames, grouping sets, LATERAL and quantified subqueries.
-- Text is never ordered (collation); every ORDER BY that decides the answer
-- ends on a unique key with NULL placement stated.

-- Time zones (Spice and the oracle run in UTC)
SELECT id, tz FROM ev WHERE tz >= TIMESTAMPTZ '2024-03-10 01:30:00-08' AND tz < TIMESTAMPTZ '2024-03-10 05:00:00-07';
SELECT id, date_trunc('day', tz) AS day, date_trunc('hour', tz) AS hour FROM ev WHERE id < 40;
SELECT id, EXTRACT(HOUR FROM tz) AS h, EXTRACT(DOW FROM tz) AS dow, EXTRACT(EPOCH FROM tz) AS e FROM ev WHERE id < 40;
-- oracle-sql: SELECT id, (tz AT TIME ZONE 'America/New_York') AS ny FROM ev WHERE id < 40
SELECT id, CAST(tz AT TIME ZONE 'America/New_York' AS TIMESTAMP) AS ny FROM ev WHERE id < 40;
SELECT CAST(tz AS DATE) AS day, count(*) FROM ev GROUP BY CAST(tz AS DATE);
SELECT id, tz + INTERVAL '1 day' AS next_day, tz - INTERVAL '90 minutes' AS before FROM ev WHERE id < 40;
SELECT id, ts - TIMESTAMP '2000-01-01 00:00:00' < INTERVAL '30 days' AS early FROM ev WHERE id < 40;
SELECT date_bin(INTERVAL '6 hours', tz, TIMESTAMPTZ '2024-01-01 00:00:00+00') AS bucket, count(*) FROM ev GROUP BY 1;
SELECT id, make_date(2024, 1 + id % 12, 1 + id % 28) AS md FROM ev WHERE id < 40;
SELECT id, to_char(dt, 'YYYY-MM-DD') AS c FROM ev WHERE id < 40;

-- JSON (jsonb reaches Spice as text)
SELECT id, j ->> 'name' AS name, j -> 'nested' ->> 'v' AS v FROM ev;
SELECT id FROM ev WHERE j ->> 'k' = '3';
SELECT j ->> 'k' AS k, count(*) FROM ev GROUP BY j ->> 'k';
SELECT id, j -> 'tags' ->> 1 AS second_tag FROM ev WHERE id < 60;
SELECT id, j ->> 'maybe' AS maybe FROM ev WHERE id < 60;
SELECT id FROM ev WHERE j ->> 'missing' IS NULL AND j IS NOT NULL AND id < 60;
SELECT id, CAST(j -> 'nested' ->> 'v' AS DOUBLE PRECISION) * 2 AS v2 FROM ev WHERE id < 60;

-- Arrays
SELECT id, a FROM ev;
SELECT id, cardinality(a) AS c FROM ev;
SELECT id, a[1] AS first, a[3] AS third FROM ev WHERE a IS NOT NULL;
-- oracle-sql: SELECT id, e FROM ev, unnest(a) AS e
SELECT id, unnest(a) AS e FROM ev;
-- oracle-sql: SELECT e, count(*) FROM ev, unnest(a) AS e GROUP BY e
SELECT e, count(*) FROM (SELECT unnest(a) AS e FROM ev) u GROUP BY e;
-- oracle-sql: SELECT id FROM ev WHERE 3 = ANY(a)
SELECT id FROM ev WHERE array_has(a, 3);
SELECT id, t FROM ev;
-- oracle-sql: SELECT id, array_to_string(t, '|') AS joined FROM ev
SELECT id, array_to_string(t, '|') AS joined FROM ev;
SELECT id, array_agg(e ORDER BY e) AS sorted FROM (SELECT id, unnest(a) AS e FROM ev WHERE id < 50) u GROUP BY id;

-- Recursive CTEs
WITH RECURSIVE r(n) AS (SELECT 1 UNION ALL SELECT dst FROM edges JOIN r ON edges.src = r.n) SELECT n FROM r;
WITH RECURSIVE c(i) AS (SELECT 1 UNION ALL SELECT i + 1 FROM c WHERE i < 50) SELECT sum(i), count(*) FROM c;
WITH RECURSIVE r(n, depth) AS (SELECT 4, 0 UNION ALL SELECT dst, depth + 1 FROM edges JOIN r ON edges.src = r.n WHERE depth < 5) SELECT n, depth FROM r;

