-- Math (doubles compared within a relative tolerance)
SELECT id, power(x, 2) AS p, sqrt(abs(x)) AS r, ln(abs(x) + 1) AS l, exp(x / 20) AS e FROM ev WHERE x IS NOT NULL;
SELECT id, sin(x) AS s, cos(x) AS c, atan2(x, n) AS a FROM ev WHERE x IS NOT NULL AND n IS NOT NULL;
SELECT id, round(d, 1) AS r1, round(d) AS r0, trunc(d, 2) AS t2, floor(d) AS f, ceil(d) AS c FROM ev;
SELECT id, n % 7 AS m, -n % 7 AS nm, mod(n, -7) AS mn FROM ev WHERE n IS NOT NULL;
SELECT id, gcd(n, 12) AS g, lcm(n, 4) AS l FROM ev WHERE n IS NOT NULL AND n <> 0;
SELECT id, abs(n) AS a, sign(n) AS s FROM ev;
SELECT id, d / 3 AS third, d * d AS sq FROM ev WHERE id < 60;
SELECT sum(d), avg(d), min(d), max(d), stddev_samp(x), var_samp(x) FROM ev;

-- Strings
SELECT id, split_part(s, ',', 2) AS p2, strpos(s, 'a') AS pos, initcap(s) AS cap FROM ev WHERE s IS NOT NULL;
SELECT id, repeat(s, 2) AS rr, translate(s, 'ae', 'AE') AS tr, ascii(s) AS a FROM ev WHERE s IS NOT NULL AND s <> '';
SELECT id, substring(s FROM 2 FOR 3) AS sub, overlay(s PLACING 'XX' FROM 2 FOR 1) AS ov FROM ev WHERE s IS NOT NULL;
-- oracle-sql: SELECT id, starts_with(s, 'Ga') AS sw, right(s, 1) = 'é' AS ew FROM ev WHERE s IS NOT NULL
SELECT id, starts_with(s, 'Ga') AS sw, ends_with(s, 'é') AS ew FROM ev WHERE s IS NOT NULL;
SELECT id, chr(65 + id % 26) AS c, md5(s) AS m FROM ev WHERE s IS NOT NULL;
SELECT id, lower(s) AS l, upper(s) AS u, length(s) AS n FROM ev WHERE s IS NOT NULL;
SELECT id, btrim(s) AS b, ltrim(s) AS l, rtrim(s) AS r FROM ev WHERE s IS NOT NULL;
SELECT id, concat_ws('-', s, n, grp) AS c FROM ev;
SELECT id, s || '#' || grp AS c FROM ev WHERE s IS NOT NULL;
SELECT id, left(s, 3) AS l, right(s, 3) AS r, reverse(s) AS rv FROM ev WHERE s IS NOT NULL;
SELECT grp, string_agg(s, '|' ORDER BY id) AS joined FROM ev WHERE s IS NOT NULL GROUP BY grp;

-- Conditionals
SELECT id, CASE WHEN n > 20 THEN 'hi' WHEN n < -20 THEN 'lo' WHEN n IS NULL THEN 'none' ELSE 'mid' END AS band FROM ev;
SELECT id, coalesce(n, x, d) AS c, nullif(n % 5, 0) AS nz FROM ev;
SELECT id, greatest(n, 0, d) AS g, least(n, 0, d) AS l FROM ev WHERE n IS NOT NULL;
SELECT id FROM ev WHERE n BETWEEN SYMMETRIC 20 AND -20;
SELECT id FROM ev WHERE (n, grp) IN ((1, 'red'), (-3, 'blue'), (12, 'green'));

-- Window frames
SELECT id, sum(n) OVER (ORDER BY id ROWS BETWEEN 3 PRECEDING AND 1 FOLLOWING) AS s FROM ev;
SELECT id, count(*) OVER (ORDER BY dt RANGE BETWEEN INTERVAL '10 days' PRECEDING AND CURRENT ROW) AS c FROM ev;
SELECT id, percent_rank() OVER (ORDER BY n NULLS FIRST, id) AS pr, cume_dist() OVER (ORDER BY n NULLS FIRST, id) AS cd FROM ev;
SELECT id, grp, first_value(n) OVER (PARTITION BY grp ORDER BY id ROWS BETWEEN 2 PRECEDING AND 2 FOLLOWING) AS fv FROM ev;
SELECT id, avg(x) OVER (PARTITION BY grp ORDER BY id) AS running FROM ev;
SELECT id, n, sum(n) OVER w AS s, max(n) OVER w AS m FROM ev WINDOW w AS (PARTITION BY grp ORDER BY id) ;

-- Grouping sets
SELECT grp, n % 2 AS parity, count(*), GROUPING(grp) AS g FROM ev GROUP BY CUBE (grp, n % 2);
SELECT grp, count(*) FROM ev GROUP BY ROLLUP (grp) HAVING count(*) > 10;

-- LATERAL and quantified subqueries
SELECT ev.id, l.doubled FROM ev, LATERAL (SELECT ev.id * 2 AS doubled) l WHERE ev.id < 30;
SELECT id FROM ev WHERE n > ALL (SELECT n FROM ev WHERE grp = 'red' AND n IS NOT NULL AND n < 0) AND id < 80;
SELECT id FROM ev WHERE n = ANY (SELECT src FROM edges) AND id < 120;
SELECT id FROM ev e WHERE EXISTS (SELECT 1 FROM edges WHERE edges.dst = e.id AND edges.src % 3 = 0);
SELECT id, (SELECT max(dst) FROM edges WHERE edges.src = e.id) AS reach FROM ev e WHERE id < 70;
